\label{main thm}
   Let $\mathbb{F}$ be a finite rank non-abelian free group and let $\phi\in \operatorname{Out}(\mathbb{F})$.
   The free-by-cyclic group $\mathbb{G} \cong \mathbb{F} \rtimes_\phi \mathbb{Z}$ is finite index rigid if and only if $\phi$ has infinite order in $\operatorname{Out}(\mathbb{F})$.

\label{reduction to normal}
The following are equivalent:
\begin{enumerate}
    \item $G$ is FIR.
    \item Every finite index subgroup of $G$ is FIR.
    \item Every finite index subgroup $H\le G$ has a finite index subgroup $K\le H$ that is nFIR.
\end{enumerate}

Let $\mathcal{G}$ be a set of groups closed under taking finite index subgroups. A \emph{multiplicative function} $\xi\colon\mathcal{G}\to \mathbb{R}$ is a 
function that satisfies:
\begin{enumerate}
    \item $\xi$ is a group invariant, i.e. if $G_1\simeq G_2$ then $\xi(G_1)=\xi(G_2)$.
    \item $\xi$ is proportional to index, i.e. if $H\le G$ has finite index then $\xi(H)=[G:H]\xi(G)$.
\end{enumerate}

\label{reduction to UPG and normal}
    Let $d\ge 1$. The following are equivalent:
    \begin{enumerate}
    \item For every UPG element $\phi$ of degree $d$, the group $\mathbb{F}\rtimes _\phi\mathbb{Z} $ is nFIR.
    \item For every polynomially growing $\phi$ of degree $d$, the group $\mathbb{F}\rtimes _\phi\mathbb{Z}$ is FIR.
    \end{enumerate}

\label{canonical tree}
    Let $\mathbb{G}=\mathbb{F} \rtimes_\phi \mathbb{Z} = \left< \mathbb{F},t  \mid  tgt^{-1} =\Phi(g) \right>$ where $\phi$ is a UPG outer automorphism of degree $d$ and $\Phi \in \operatorname{Aut}(\mathbb{F})$ represents $\phi$.

    Then there exists a tree $\mathbb{T} = \mathbb{T}_\mathbb{G}$ and a minimal action $\mathbb{G}\curvearrowright \mathbb{T}$ such that:
    \begin{enumerate}[label = (T\arabic*)]
        \item\label{T: vertex groups} 
        Vertex groups are polynomial free-by-cyclic \footnote{Here \emph{free-by-cyclic} includes degenerate cases, such as $\mathbb{Z}=1\rtimes \mathbb{Z}$ and $\mathbb{Z}^2=\mathbb{Z}\rtimes \mathbb{Z}$, which are clearly polynomially growing of degree $0$.} groups of degree at most $d-1$, with at least one vertex group of degree equal to $d-1$. 
        \item \label{T: finite index}
        If $H\le \mathbb{G}$ has finite index, then $\mathbb{T}_H$ is $H$-equivariantly isomorphic to $\mathbb{T}_G$.
        \item\label{T: commensurability invariance} If $\eta\colon H\to H'\le \mathbb{G}$ is an isomorphism between finite index subgroups $H,H'\le \mathbb{G}$, then there is an $\eta$-equivariant isomorphism $H\curvearrowright \mathbb{T}_\mathbb{G}\to H'\curvearrowright \mathbb{T}_\mathbb{G}$. 
    \end{enumerate}
    If $d=1$, then moreover
    \begin{enumerate}[label = (T\arabic*)]\setcounter{enumi}{3}
        \item\label{T: edge groups linear} Edge groups are maximal $\mathbb{Z}^2$ subgroups of $\mathbb{G}$.
        \item\label{T: vertex groups linear} The tree has a bipartition $V(\mathbb{T}) = V_0 \sqcup V_1$. The stabilizers of vertices in $V_0$ are of the form $F \times \left< yt \right>$ where $F\le \mathbb{F}$ is non-abelian and $y\in \mathbb{F}$; and those of vertices in $V_1$ are isomorphic to $\mathbb{Z}^2$. 
        \item\label{T: cylinders linear} Every vertex in $V_1$ has finite valence.
    \end{enumerate}

\label{eg:limiting tree}
    Let $\mathbb{F} = \left< a, b \right>$ and $\phi \in \operatorname{Out}(\mathbb{F})$ be the outer class of  $ \Phi \colon a \mapsto a, b \mapsto ba$. Let \[\mathbb{G} = \mathbb{F} \rtimes_\phi \mathbb{Z} = \left< a, b, t \mid  tat^{-1} = a, tbt^{-1} = ba \right>.\] 
    The tree $\mathbb{F} \curvearrowright T_\phi$ is obtained by the construction of the limiting tree explained in \cite[Lemma 4.37]{BFH:TitsII}. 
   In \Cref{fig:Example1} the left figure shows $T_\phi/\mathbb{F}$ with graph of groups edge inclusion maps given by 
    $\mathbb{Z} \to\left< b^{-1} ab \right>$, $\mathbb{Z} \to \left< a \right>$ 
    and the right figure shows $T_\phi/\mathbb{G}$ with 

    graph of groups edge inclusion maps
    $\mathbb{Z}^2 \to \left< b^{-1} ab, at \right>$, $\mathbb{Z}^2 \to \left< a, batb^{-1} \right> = \left< a, t \right>$.
    The tree of cylinders $\mathbb{T}$ is simply the barycentric subdivision of $T_\phi$.

\begin{figure}[htbp]
  \centering
    \includegraphics[scale=.6]{Example1.pdf}
    \caption{$T_\phi/\mathbb{F}$ and $T_\phi/\mathbb{G}$ }
    \label{fig:Example1}
\end{figure}

Recall the setup from \Cref{eg:limiting tree}. 
Note that $\mathbf{T}$ is isomorphic to $T_\phi$ in this example.                                                                                            
Let $A < \mathbb{F}$ be an index 2 subgroup given by $\left<  a^2,b, aba^{-1} \right>$. 
In \Cref{fig:Example2}, the left figure shows $\mathbf{T}/A$.













   Note that $A$ is not $\Phi$-invariant but it is $\Phi^2$-invariant. 
Therefore, the subgroup $H=\left< A,t^4 \right> <\mathbb{G}$ has index 8 in $\mathbb{G}$ and has the form 
$H = A \rtimes_{\Phi^4|_A} \mathbb{Z}$ with monodromy represented by $t^4$. In \Cref{fig:Example2}, the right figure shows $\mathbf{T}/H$ with vertex $\hat v$ and edge $\hat e$. The 
graph of groups inclusion maps for $\hat e$ are $\mathbb{Z}^2 \to \left< b^{-1} a^2b, a^4t^4 \right>$ and $\mathbb{Z}^2 \to \left< a^2, t^4 \right>$. Let $\widetilde{e}$ be a lift of  $\hat{e}$ with stabilizer $\left< a^2, t^4 \right>$ and with end points $v_1, v_2$. Then $Z_1 = \left< a^4t^4 \right>$ and $Z_2 = \left< t^4 \right>$.  Using $e,v$ to denote the edge and vertex of $\mathbf{T}/\mathbb{G}$ shown in \Cref{fig:Example1}, we get

\begin{align*}
     \Delta(e) & = [\left< a,t \right> : \left< t \right>+ \left< at \right> ] = 1  & \mathbf{x}(v)&=-1 & \alpha(e)&=\frac{1}{\Delta(e)\mathbf{x}(v)^2}=1\\
     \Delta(\hat e) & = [\left< a^2,t^4 \right> : \left< t^4 \right>+ \left< a^4 t^4 \right> ] = 2 & \mathbf{x}(v')&=-2  & \alpha(\hat e)&=\frac{1}{\Delta(e_1)\mathbf{x}(v')^2}= \frac{1}{8}
    \end{align*}     

\begin{figure}[htbp]
  \centering
    \includegraphics[scale=.6]{Example2.pdf}
    \caption{$\mathbf{T}/A$ and $\mathbf{T}/H$ }
    \label{fig:Example2}
\end{figure}

\label{alpha of cover}
    Let $\hat G\lhd \mathbb{G}$ be a normal subgroup of index $d$. Denote by $p\colon \Gamma(\hat G)=\mathbf{T}/\hat G\to \mathbf{T}/\mathbb{G}=\Gamma(\mathbb{G})$ the quotient map. 
    Let $e$ be an edge of $\Gamma(\mathbb{G})$ with endpoints $v_1,v_2$ and let $\hat e$ be an edge of $\Gamma(\hat G)$ with $p(\hat e)=e$. Let $u_i = |p^{-1} (v_i)|$ and $u_e = |p^{-1}(e)|$.  Then
    \begin{equation}
        \label{desired equality} d u_e\alpha(\hat e) = \alpha(e)u_1u_2.
    \end{equation}

Let $\tilde e$ be an edge of $\mathbf{T}$ which lifts $e$ and $\hat e$, and let $\tilde v_1$ and $\tilde v_2$ be the end points of $\tilde e$. 
    Denote by $G_i = \mathbb{G}_{\tilde v_i}$ (resp. $\hat G_i = \hat G_{\tilde v_i}$) the stabilizer of $\tilde v_i$ in $\mathbb{G}$ (resp. $\hat G$) . 
    Then, since $\hat G\lhd \mathbb{G}$, \Cref{sum of indices} implies
    \begin{equation}\label{eq1}
        d=[\mathbb{G}:\hat G]=[G_i:\hat G_i] u_i.
    \end{equation}
    Recall that $G_i\simeq F_i \times Z_i$ where $F_i$ is free of rank at least 2 and $Z_i = Z(G_i)\simeq \mathbb{Z}$. 
    Similarly, $\hat G_i=\hat F_i\times \hat  Z_i$ where $\hat F_i = F_i \cap \hat G_i$ and $\hat Z_i$ is the image of $\hat G_i$ under the projection $G_i \twoheadrightarrow Z_i$.
    Then, 
    \begin{equation}
        \label{eq2}[G_i:\hat G_i]=[Z_i:\hat Z_i][F_i:\hat F_i]
    \end{equation}
    Since the Euler characteristic is proportional to index, we get for endpoints $\hat v_i$ of $\hat e$,
    \begin{equation}
        \label{eq3}\mathbf{x}(\hat v_i)=\chi(\hat F_i) = [F_i:\hat F_i]\chi(F_i) = [F_i:\hat F_i]\mathbf{x}(v_i).
    \end{equation}
    Similarly, denote $E = G_{\tilde e}$ and $\hat E = \hat G_{\tilde e}$, the stabilizers of $\tilde e$ in $\mathbb{G}$ and $\hat{G}$, respectively.
    Then,
    \begin{equation}
        \label{eq4} d=[E:\hat E] u_e
    \end{equation}
    Finally, since $\Delta(e) = [E:Z_1+Z_2]$ and $\Delta(\hat e) = [\hat E:\hat Z_1+\hat Z_2]$, we have
    \begin{equation}
        \label{eq5} [Z_1:\hat Z_1][Z_2:\hat Z_2]\Delta(e)=[E:\hat Z_1+\hat Z_2]=\Delta(\hat e)[E:\hat E]
    \end{equation}

    Combining \Cref{eq1,eq2,eq3,eq4,eq5} gives the desired equality \eqref{desired equality}.
